#![cfg(test)]
//! Golden vectors for the delivery-claim leaf.
//!
//! The same vectors live in `packages/claims/test/vectors.json` (generated by
//! `packages/claims/test/gen-vectors.mjs` with node:crypto only) and are asserted by
//! the TypeScript claim builder, so the off-chain anchoring job and this contract
//! agree byte for byte. Inputs are fixed pseudo-random values and fake parcel data.
extern crate std;
use std::println;

use super::{leaf, Claim};
use soroban_sdk::{Address, BytesN, Env, String as SStr, Vec};

/// (escrow C-address, order_ref, parcels_commit, carrier_event_ref, delivered_at, expected leaf)
const VECTORS: [(&str, &str, &str, &str, u64, &str); 3] = [
    (
        "CAUAHHXQBES5QLDBD3YIRKFWK2SHOWVTRTJ55CTDBP57BM7FJUYFIH6J",
        "3ae1008ad5063ae77c13366d218c99d5a4c0cacbb77aa5e5e0d12068392c1f4b",
        "f6fbdf86de0b2bb068fbc5b2ea8ecfee19bb61dfdf9d668edd2fcc981bdf8d82",
        "2e6c4f30219f2a3f5aa1e473d308dc87c126c88b5440681470d82114d649bcb9",
        0,
        "03fe1e79907aa82656344e9f84a6a9b33900c11d45128f5d4ffb809911455b05",
    ),
    (
        "CCCIWGVN2SUC6WDFABPXRRAV4QNV66JICSFUNSKGUIO6XE4CQZ4OBZFG",
        "901d8f8204f22afbb624b5c53d5eb1ee96c530263e86b87e32f8c7bae9c15545",
        "6a4625181a19e36bf05dfa8fc636f0fc3a8f987fda3d0840564342f69fc3b899",
        "fe58a60b1315baa313664ebb50e691f21c7d0534c93ab90f3ac1749fa159d1fe",
        1_761_337_000,
        "30716e3b5321ed93a3ce1910143838ffa61d4cabab2cbda2f1f6d5de763f8807",
    ),
    (
        "CDZBPFXKJRFMGECACCIR5WPKPVELGZC7QU4J7Y2PHIPVD2CMZJND6M3X",
        "9c5926bf7f63735cc8cb6019a93c6bb9a2c15c3a8db02fd47ae759874c94b77f",
        "9ba41b1e9e64abedf46536e0e9b87d91c932b06e0ffac6576da6ca2eb2f8c2d1",
        "476e027743cbaf9c7cbe1a00fc0dce9bac95d3c8f78927f7213af255042c1342",
        u64::MAX,
        "1e11572e3d78b8324cbd011256e02f7ed001575a9b3a45b999b551e46a2d31e1",
    ),
];

fn h32(env: &Env, s: &str) -> BytesN<32> {
    assert_eq!(s.len(), 64);
    let mut a = [0u8; 32];
    for (i, byte) in a.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap();
    }
    BytesN::from_array(env, &a)
}

fn hex(b: &BytesN<32>) -> std::string::String {
    b.to_array().iter().map(|x| std::format!("{:02x}", x)).collect()
}

#[test]
fn claim_leaf_golden_vectors() {
    let env = Env::default();
    for (escrow, order_ref, parcels_commit, carrier_event_ref, delivered_at, expected) in VECTORS {
        let e = Address::from_string(&SStr::from_str(&env, escrow));
        let c = Claim {
            order_ref: h32(&env, order_ref),
            parcels_commit: h32(&env, parcels_commit),
            carrier_event_ref: h32(&env, carrier_event_ref),
            delivered_at,
            batch_id: 0,
            proof: Vec::new(&env),
            index: 0,
        };
        let got = leaf(&env, &e, &c);
        println!("claim leaf vector {escrow} delivered_at={delivered_at} -> {}", hex(&got));
        assert_eq!(got, h32(&env, expected));
    }
}

/// The leaf ignores batch_id, proof and index: they locate the leaf, they are not part of it.
#[test]
fn claim_leaf_ignores_position_fields() {
    let env = Env::default();
    let (escrow, o, p, r, at, expected) = VECTORS[1];
    let e = Address::from_string(&SStr::from_str(&env, escrow));
    let mut proof = Vec::new(&env);
    proof.push_back(h32(&env, o));
    let c = Claim {
        order_ref: h32(&env, o),
        parcels_commit: h32(&env, p),
        carrier_event_ref: h32(&env, r),
        delivered_at: at,
        batch_id: 489_260,
        proof,
        index: 7,
    };
    assert_eq!(leaf(&env, &e, &c), h32(&env, expected));
}
